const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const provinceName = 'Sistan and Baluchestan';
  const startDate = '2020-01-08';
  const endDate = '2020-01-15';

  // Get Sistan-Baluchestan boundary from FAO GAUL dataset
  const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const province = gaul.filter(ee.Filter.eq('ADM1_NAME', provinceName));

  // 2. Data Acquisition - GPM IMERG precipitation data
  const gpm = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(province);

  const collectionSize = gpm.size().getInfo();
  console.log(`GPM Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Sum precipitation over the period (mm)
  const totalPrecip = gpm.select('precipitationCal').sum();

  // 3. Processing - Check valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: province,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  console.log(`Valid Pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation and convert to inches
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: province,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitationCal').getInfo();

  const inches = meanPrecip / 25.4; // Convert mm to inches

  console.log(`Mean Rainfall: ${inches.toFixed(2)} inches`);

  // 5. Validation & Final Answer
  if (meanPrecip === null || !isFinite(meanPrecip) || inches < 0 || inches > 1000) {
    console.log("<answer>C3</answer>");
  } else if (inches > 3) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
